  summonedWeaponDamageBonus?: number
  summonedProficientSkillCheckBonus?: number
  summonedAttacksPerAction?: number
  summonedShareSelfSpellsRangeFeet?: number
  summonedShareSelfSpellsRequiresMounted?: boolean
  /** Host-owned restriction used by familiars and other non-attacking companions. */
  summonedCannotAttack?: boolean
  summonedCommandPolicy?: 'persistent-order' | 'turn-order'
  summonedBondKey?:string
  summonedAutonomousBehavior?: 'attack-nearest-visible' | 'attack-nearest-other-subtype' | 'protect-source'
  summonedUncontrolledSubtype?:string
  summonedControlSubtype?:string
  protectedFromActorIds?:readonly string[]
  summonedSourceActivityId?: string
  summonedSourcePackageId?: string
  summonedSourceCombatantId?: string
  /** Lifetime binding survives loss of command authority. */
  summonedDeathSourceCombatantId?: string
  summonedDeathSourceCharacterId?: string
