  summonedDeathSourceConfirmedDead?: boolean
  summonedSourceDeathHandled?: boolean
  /** Host map snapshot: only persistent summons may receive companion commands. */
  summonedPersistent?: boolean
  /** Simulacrum spell slots are spend-only for the lifetime of the duplicate. */
  simulacrumCannotRegainSpellSlots?: boolean
  /** Simulacrum ignores ordinary healing; only its dedicated repair workflow may restore HP. */
  simulacrumCannotRegainHitPoints?: boolean
  wearingArmor: boolean
  wearingUnproficientArmor: boolean
  armorStealthDisadvantage: boolean
  wearingHeavyArmor: boolean
  wearingMetalArmor: boolean
  equippedArmor?: {
    instanceId: string
    equipmentId: string
    magical: boolean
    metal: boolean
    baseProvidedArmorClass: number
    armorClassPenalty: number
    unarmoredArmorClass: number
    destroyed: boolean
  }
  hasShield: boolean
  /** Closed equipment facts exposed to Activity predicates; never client-authored at execution time. */
  lastLongRestWorldMinute?: number | null
  activityEquipment?: Dnd5eActivityEquipmentSnapshotV1
  /** Class ids are informative; `capable` also covers approved subclass spellcasting. */
  activitySpellcasting?: { capable: boolean; classIds: readonly string[] }
  /** Number of currently usable hands for independent basic-action grapples. */
  grappleFreeHandCapacity?: number
  /** 地图快照中的主手武器，用于验证只强化施法时所持的武器。 */
  mainWeaponId?: string
  /** 主手武器本身是否已经是魔法武器；魔化武器不能以它为目标。 */
