/**
 * Canonical spell-effect inventory used by both player and monster Dispel
 * Magic paths.  In particular this preserves the actual slot level stored on
 * an active effect or its concentrating source instead of falling back to the
 * spell catalogue's base level in the UI.
 */
export function dnd5eSpellDurationIsInstantaneous(spellId: string): boolean {
  // SRD catalogue entries have no duration field; use the reviewed metadata,
  // not the effect's remaining lifetime or prose matching. Imported durations
  // are already structured and must not be inferred from lingering outcomes.
  return getDnd5eSrdSpellCatalogEntry(spellId)
    ? DND5E_SRD_SPELL_DESCRIPTIONS_ZH_REVIEWED[spellId]?.duration.trim() === '立即'
    : dnd5ePluginSpellDefinition(spellId)?.duration.type === 'instantaneous'
}

export function dnd5eDispelMagicEffectsOnTarget(
  state: Dnd5eHeadlessCombatState,
  targetId: string,
): Dnd5eDispelMagicEffect[] {
  const target = state.combatants[targetId]
  if (!target) return []
  const spellEffects = new Map<string, Dnd5eDispelMagicEffect>()
  for (const effect of target.classState.activeEffects ?? []) {
    if (effect.source.kind !== 'spell' || !effect.source.rulesId || effect.linkedLifetime?.protectedRemoval || dnd5eSpellDurationIsInstantaneous(effect.source.rulesId)) continue
    const catalog = getDnd5eSrdSpellCatalogEntry(effect.source.rulesId) ?? dnd5ePluginSpellDefinition(effect.source.rulesId)
    if (!catalog) continue
    const key = `${effect.source.actorId ?? 'unknown'}\u0000${catalog.id}`
    if (!spellEffects.has(key)) {
      spellEffects.set(key, {
        spellId: catalog.id,
        spellLevel: effect.source.spellLevel ?? catalog.level,
        effectId: effect.id,
        sourceActorId: effect.source.actorId,
      })
    }
  }
  for (const [sourceActorId, spellId] of Object.entries(
    target.classState.concentrationEffectsBySource ?? {},
  )) {
    if (dnd5eSpellDurationIsInstantaneous(spellId)) continue
    const ownedEffects = (target.classState.activeEffects ?? []).filter(effect =>
      effect.source.kind === 'spell' && effect.source.rulesId === spellId && effect.source.actorId === sourceActorId)
    if (ownedEffects.length && ownedEffects.every(effect => effect.linkedLifetime?.protectedRemoval)) continue
    const catalog = getDnd5eSrdSpellCatalogEntry(spellId) ?? dnd5ePluginSpellDefinition(spellId)
    if (!catalog) continue
    const key = `${sourceActorId}\u0000${catalog.id}`
    if (spellEffects.has(key)) continue
    const source = state.combatants[sourceActorId]
    spellEffects.set(key, {
      spellId: catalog.id,
      spellLevel: source?.classState.concentrationSpellId === catalog.id
        ? source.classState.concentrationSpellLevel ?? catalog.level
        : catalog.level,
      effectId: `concentration:${sourceActorId}:${catalog.id}`,
      sourceActorId,
    })
  }
  return [...spellEffects.values()]
}

