export interface Dnd5eAttackDecoyRoll {
  effectId: string
  redirectD20: number
}

export interface Dnd5eAttackDecoyOccurrenceRoll extends Dnd5eAttackDecoyRoll {
  occurrenceId: string
}

export function dnd5eBasicAttackTargetEligible(state: Dnd5eHeadlessCombatState, actorId: string, targetId: string): boolean {
  const actor = state.combatants[actorId], target = state.combatants[targetId]
  return !!actor && !!target && actorId !== targetId && target.currentHp > 0 && !target.deathSaves.dead &&
    dnd5eCombatantPerceivesHostile(state, actorId, targetId) &&
    dnd5eEffectiveSizeRank(target) <= dnd5eEffectiveSizeRank(actor) + 1 &&
    dnd5eAttackDistanceFeet(state, actorId, targetId) <= 5 &&
    state.lineOfEffectBlockedByCombatantPair?.[dnd5eDirectedCombatantPairKey(actorId, targetId)] !== true
}

export function dnd5eBasicHelpTargetEligible(state: Dnd5eHeadlessCombatState, actorId: string, targetId: string, kind: 'attack' | 'ability-check'): boolean {
  const actor = state.combatants[actorId], target = state.combatants[targetId]
  return !!actor && !!target && actorId !== targetId && target.currentHp > 0 && !target.deathSaves.dead &&
    (kind === 'ability-check' ? target.controller === actor.controller :
      dnd5eCombatantPerceivesHostile(state, actorId, targetId) && dnd5eAttackDistanceFeet(state, actorId, targetId) <= 5)
}

export function dnd5eBasicWakeTargetEligible(state: Dnd5eHeadlessCombatState, actorId: string, targetId: string): boolean {
  const target = state.combatants[targetId]
  return !!state.combatants[actorId] && !!target && actorId !== targetId && target.currentHp > 0 && !target.deathSaves.dead &&
    dnd5eAttackDistanceFeet(state, actorId, targetId) <= 5 &&
    !state.lineOfEffectBlockedByCombatantPair?.[dnd5eDirectedCombatantPairKey(actorId, targetId)] &&
    reconciledDnd5eActiveEffects(target).some(effect => effect.breakOn?.includes('awakened') === true ||
      effect.standardCondition === 'unconscious' && effect.source.kind === 'spell' && effect.source.rulesId === 'sleep')
}

export interface Dnd5eMonsterActionRoll {
  targetId: string
  attackDecoyRoll?: Dnd5eAttackDecoyRoll
  d20: number
  d20Second?: number
  blessRoll?: number
  baneRoll?: number
  bardicInspirationRoll?: number
  cuttingWords?: Dnd5eCuttingWordsUse
  cuttingWordsDamage?: Dnd5eCuttingWordsUse
  postD20Adjustment?: Dnd5ePostD20AdjustmentUse
  mode?: D20RollMode
  /**
   * Host-authored final mode for a DM-controlled monster attack. Unlike
   * `mode`, this is not another advantage/disadvantage source: the authority
   * has already applied the DM ruling and any reaction that occurred before
   * the dice were rolled.
   */
  dmFinalMode?: D20RollMode
  areaAttackAdvantageReaction?: { areaId: string; sourceId: string }; protectionReactionActorId?: string
  attackRetargetInterrupt?: Dnd5eAttackRetargetInterruptUse
  mountedAttackRedirect?: Dnd5eMountedAttackRedirectUse
  shieldSpellReaction?: boolean
  uncannyDodge?: boolean
  deflectMissilesD10?: number
  tranquilitySave?: Dnd5eTranquilitySaveRoll
  damageRolls: readonly (readonly number[])[]
  /** Dice for the first qualifying once-per-turn catalog attack trait. */
  traitDamageRolls?: readonly {
    traitId: 'sneak-attack' | 'martial-advantage' | 'charge-damage' | 'dive-damage'
    rolls: readonly number[]
  }[]
  /**
   * Host-authored resolutions for this concrete attack occurrence. Multiattack
   * repeats carry separate arrays, so one hit can never overwrite another.
   */
  onHitEffectRolls?: readonly Dnd5eMonsterOnHitEffectRoll[]
  sizeDamageRolls?: readonly number[]
  standAgainstTide?: Dnd5eStandAgainstTideUse
}

export interface Dnd5eMonsterOnHitEffectRoll {
  sourceDisadvantageNegationChoice?: Dnd5eActiveEffectSavingThrowRoll['disadvantageNegationChoice']
  disadvantageNegationChoice?: Dnd5eActiveEffectSavingThrowRoll['disadvantageNegationChoice']
  effectId: string
  /** Required only by effects that actually resolve a saving throw. */
  d20?: number
  d20Second?: number
  halflingLuckyD20?: number
  halflingLuckyD20Second?: number
  blessRoll?: number
  baneRoll?: number
  rerollResourceKey?: string; rerollD20?: number
  rerollD20Second?: number
  bardicInspirationRoll?: number
  darkOnesOwnLuckRoll?: number
  postD20Adjustment?: Dnd5ePostD20AdjustmentUse
  legendaryResistance?: boolean
  /** Source-side dice for an opposed ability check. `d20` remains target-side. */
  sourceD20?: number
  sourceD20Second?: number
  /** Host-authored, geometry-truncated forced-movement result. */
  forcedMovement?: Dnd5eSpellForcedMovement
  /** Required only by effects that roll damage after the hit. */
  damageRolls?: readonly (readonly number[])[]
  /** Shared severe-failure duration dice declared by the matching effect. */
  durationRolls?: readonly number[]
}

