          dnd5eTargetIsUnseenForAttack(state, actor.id, affectedTarget.id) ||
          dnd5eSourceMarkedAttackDisadvantage(actor, affectedTarget, state) ||
          dnd5eRageAllyProtectionDisadvantage(state, actor, affectedTarget)
